def transform(grid):
    h, w = len(grid), len(grid[0])
    row_lines = [r for r in range(h) if all(x == 8 for x in grid[r])]
    col_lines = [c for c in range(w) if all(grid[r][c] == 8 for r in range(h))]

    rs = [0] + [r + 1 for r in row_lines]
    re = row_lines + [h]
    cs = [0] + [c + 1 for c in col_lines]
    ce = col_lines + [w]
    nr, nc = len(rs), len(cs)

    cells = {}
    for i in range(nr):
        for j in range(nc):
            colors = {grid[r][c] for r in range(rs[i], re[i])
                      for c in range(cs[j], ce[j]) if grid[r][c] != 0}
            if colors:
                cells[i, j] = next(iter(colors))

    # Each pair of same-colored markers on a common row or column defines
    # a filled segment; multiple segments of the same color are allowed.
    segments = []
    for color in (2, 3):
        points = [(i, j) for (i, j), v in cells.items() if v == color]
        for a in range(len(points)):
            for b in range(a + 1, len(points)):
                i1, j1 = points[a]
                i2, j2 = points[b]
                if i1 == i2:
                    segments.append((color, "row", i1, min(j1, j2), max(j1, j2)))
                if j1 == j2:
                    segments.append((color, "col", j1, min(i1, i2), max(i1, i2)))

    out = [row[:] for row in grid]
    for i in range(nr):
        for j in range(nc):
            colors = set()
            for color, axis, fixed, lo, hi in segments:
                if axis == "row" and i == fixed and lo <= j <= hi:
                    colors.add(color)
                elif axis == "col" and j == fixed and lo <= i <= hi:
                    colors.add(color)
            if colors:
                fill = 6 if len(colors) > 1 else next(iter(colors))
                for r in range(rs[i], re[i]):
                    for c in range(cs[j], ce[j]):
                        out[r][c] = fill
    return out
